const __pageData = JSON.parse('{"title":"Nicolás Maduro","description":"","frontmatter":{"title":"Nicolás Maduro","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["venezuela","maduro","regime-change","oil","sanctions"],"sources":["raw/badlands-brief-02a.md","raw/badlands-brief-094.md","raw/badlands-brief-1ce.md","raw/badlands-brief-577.md","raw/badlands-brief-95a.md","raw/badlands-brief-990.md","raw/badlands-brief-708.md","raw/badlands-brief-9f2.md","raw/badlands-brief-d17.md","raw/badlands-brief-d9f.md","raw/badlands-brief-e3b.md","raw/badlands-brief-e8d.md","raw/badlands-brief.md","raw/badlands-news-brief-066.md","raw/badlands-news-brief-060.md","raw/badlands-news-brief-06e.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0b0.md","raw/badlands-news-brief-0ef.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-222.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-2f5.md","raw/badlands-news-brief-306.md","raw/badlands-news-brief-355.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-491.md","raw/badlands-news-brief-497.md","raw/badlands-news-brief-4cf.md","raw/badlands-news-brief-52f.md","raw/badlands-news-brief-779.md","raw/badlands-news-brief-763.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-7e8.md","raw/badlands-news-brief-824.md","raw/badlands-news-brief-8ce.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/nicolas-maduro.md","filePath":"entities/nicolas-maduro.md","lastUpdated":null}');
